-- Service: tasks  (per cell)
-- GENERATED by tools/split.py from plan/db/*.sql. Edit the source files or split.py, then re-run.
-- Load order: _prelude.sql, tasks.sql, _epilogue.sql
CREATE TABLE tasks (
  id               uuid PRIMARY KEY,                     -- client-generated (PROVEN: client-made ids)
  workspace_id     uuid NOT NULL /* id -> access.workspaces */,
  task_number      bigint NOT NULL,                      -- human id within workspace; ASSUMED
  home_list_id     uuid NOT NULL /* id -> hierarchy.lists */,   -- list that owns status + permissions; ASSUMED. Also present in task_list_memberships with is_home
  parent_task_id   uuid REFERENCES tasks(id),            -- subtask (PROVEN)
  root_task_id     uuid REFERENCES tasks(id),            -- top ancestor, denormalized for "whole tree" reads. ASSUMED (NULL for top-level)
  subtask_position text COLLATE "C",                     -- order among siblings. ASSUMED
  task_type_id     uuid /* id -> hierarchy.task_types */,
  status_id        uuid NOT NULL /* id -> hierarchy.task_statuses */,
  title            text NOT NULL,
  description      text,                                 -- markdown/plain projection (for search); rich body format not observed
  description_format text NOT NULL DEFAULT 'markdown' CHECK (description_format IN ('markdown','plain')), -- ASSUMED
  priority         smallint CHECK (priority BETWEEN 1 AND 4),  -- 1 urgent..4 low; NULL none. ASSUMED mapping
  start_at         timestamptz,
  start_has_time   boolean NOT NULL DEFAULT false,
  due_at           timestamptz,
  due_has_time     boolean NOT NULL DEFAULT false,
  points           numeric(10,2),                        -- sprint points (PROVEN history type "points")
  time_estimate_seconds integer CHECK (time_estimate_seconds >= 0),  -- estimate is a task field here; entries are other half
  creator_id       uuid /* id -> identity.users */,
  closed_at        timestamptz,                          -- set when status category becomes done/closed. ASSUMED
  archived_at      timestamptz,
  deleted_at       timestamptz,
  deleted_by       uuid /* id -> identity.users */,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  version          integer NOT NULL DEFAULT 1,
  CHECK (parent_task_id IS NULL OR parent_task_id <> id),
  CHECK (due_at IS NULL OR start_at IS NULL OR start_at <= due_at)
);

CREATE UNIQUE INDEX tasks_ws_number_uk ON tasks (workspace_id, task_number);

-- Tasks whose home is list L (counts, bulk move, status migration). Ordered reads use task_list_memberships instead.
CREATE INDEX tasks_home_list_idx ON tasks (workspace_id, home_list_id, status_id) WHERE deleted_at IS NULL;

-- Subtasks of a task in order.
CREATE INDEX tasks_parent_idx ON tasks (workspace_id, parent_task_id, subtask_position) WHERE parent_task_id IS NOT NULL AND deleted_at IS NULL;

CREATE INDEX tasks_root_idx ON tasks (workspace_id, root_task_id) WHERE root_task_id IS NOT NULL;

-- Forced status replacement: find all tasks on a status.
CREATE INDEX tasks_status_idx ON tasks (workspace_id, status_id) WHERE deleted_at IS NULL;

-- Calendar / due-soon / overdue.
CREATE INDEX tasks_due_idx ON tasks (workspace_id, due_at) WHERE due_at IS NOT NULL AND deleted_at IS NULL AND closed_at IS NULL;

-- Trash screen (restore within retention).
CREATE INDEX tasks_trash_idx ON tasks (workspace_id, deleted_at) WHERE deleted_at IS NOT NULL;

CREATE INDEX tasks_type_idx ON tasks (workspace_id, task_type_id) WHERE task_type_id IS NOT NULL AND deleted_at IS NULL;

-- A task can live in several lists (PROVEN: tasks in multiple lists). The row with is_home mirrors tasks.home_list_id.
-- `position` is ONE list-wide fractional key; a board column is the same order filtered by group value, so a
-- single key per (list, task) orders every column and every grouping. ASSUMED
CREATE TABLE task_list_memberships (
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  task_id       uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  list_id       uuid NOT NULL /* id -> hierarchy.lists */,
  position      text NOT NULL COLLATE "C" CHECK (position ~ '^[0-9A-Za-z]+$'),   -- base62 fractional index
  is_home       boolean NOT NULL DEFAULT false,
  added_by      uuid /* id -> identity.users */,
  added_at      timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1,
  PRIMARY KEY (task_id, list_id)
);

-- HOT: tasks of a list in order (keyset pagination on (position, task_id)).
CREATE UNIQUE INDEX tlm_list_order_uk ON task_list_memberships (workspace_id, list_id, position, task_id);

-- Exactly one home membership per task.
CREATE UNIQUE INDEX tlm_one_home_uk ON task_list_memberships (task_id) WHERE is_home;

-- "Which lists is task T in".
CREATE INDEX tlm_task_idx ON task_list_memberships (workspace_id, task_id);

CREATE TABLE task_assignees (
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  task_id       uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  user_id       uuid NOT NULL /* id -> identity.users */,
