CREATE INDEX task_group_assignees_group_idx ON task_group_assignees (workspace_id, group_id, task_id);

CREATE TABLE task_watchers (                            -- PROVEN followers; sources ASSUMED
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  task_id       uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
