-- website/email/phone was NOT captured: ASSUMED.
CREATE TABLE custom_fields (
  id               uuid PRIMARY KEY,
  workspace_id     uuid NOT NULL /* id -> access.workspaces */,
  name             text NOT NULL,                        -- PROVEN
  description      text,                                 -- PROVEN
  field_type       text NOT NULL CHECK (field_type IN (
                     'short_text','long_text','number','money','dropdown','labels','checkbox','date','people',
                     'relationship','rating','website','email','phone','progress_manual','progress_auto',
                     'location','files','signature','voting','button','formula','rollup')),
  type_config      jsonb NOT NULL DEFAULT '{}',          -- PROVEN per-type config: number_format, currency, precision, emoji count, sorting...
  is_computed      boolean GENERATED ALWAYS AS (field_type IN ('formula','rollup')) STORED,
  required         boolean NOT NULL DEFAULT false,       -- PROVEN
  required_on_subtasks boolean NOT NULL DEFAULT false,   -- PROVEN
  pinned           boolean NOT NULL DEFAULT false,       -- PROVEN
  hide_from_guests boolean NOT NULL DEFAULT false,       -- PROVEN
  is_private       boolean NOT NULL DEFAULT false,       -- PROVEN (private + members[] + groups[])
  permission_level smallint,                             -- PROVEN request field; meaning ASSUMED
  is_workspace_wide boolean NOT NULL DEFAULT false,      -- applies everywhere without location rows. ASSUMED
  inverse_field_id uuid REFERENCES custom_fields(id),    -- relationship backlink mirror (PROVEN inverted_field)
  position         text NOT NULL COLLATE "C",
  created_by       uuid /* id -> identity.users */,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
