CREATE UNIQUE INDEX custom_field_access_user_uk  ON custom_field_access (field_id, user_id)  WHERE user_id IS NOT NULL;

CREATE UNIQUE INDEX custom_field_access_group_uk ON custom_field_access (field_id, group_id) WHERE group_id IS NOT NULL;

-- Dropdown/labels options as rows (values reference them by FK). PROVEN: options have uuid, name, color, orderindex.
CREATE TABLE custom_field_options (
  id            uuid PRIMARY KEY,
