CREATE INDEX custom_field_options_field_idx ON custom_field_options (workspace_id, field_id, position) WHERE deleted_at IS NULL;

-- Where a field is attached: a space, folder or list (PROVEN: locations PUT with parent type 6 = list; space/folder ASSUMED).
-- Applies to the container and everything below it (descendants found via containers.ancestor_ids).
CREATE TABLE custom_field_locations (
  id            uuid PRIMARY KEY,
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  field_id      uuid NOT NULL REFERENCES custom_fields(id) ON DELETE CASCADE,
