CREATE UNIQUE INDEX custom_field_locations_uk ON custom_field_locations (field_id, container_id);

-- "Fields visible in list L": WHERE container_id = ANY(ancestor_ids of L).
CREATE INDEX custom_field_locations_container_idx ON custom_field_locations (workspace_id, container_id, field_id);

-- Values: typed scalar columns on one row per (task, field). Set-valued fields use custom_field_value_items.
-- Date value = epoch-ms string on the wire (PROVEN) -> value_ts + value_has_time here.
CREATE TABLE custom_field_values (
  workspace_id   uuid NOT NULL /* id -> access.workspaces */,
  task_id        uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  field_id       uuid NOT NULL REFERENCES custom_fields(id),
  value_text     text,                                   -- short/long text, website, email, phone
  value_num      numeric,                                -- number, money (currency in type_config), rating, progress
  value_ts       timestamptz,                            -- date
  value_has_time boolean,                                -- PROVEN value_options {time:false}
  value_bool     boolean,                                -- checkbox
  option_id      uuid REFERENCES custom_field_options(id),  -- dropdown (single select; PROVEN value = option uuid)
  value_json     jsonb,                                  -- ONLY for unfilterable shapes (location, signature, button). ASSUMED
  is_stale       boolean NOT NULL DEFAULT false,         -- computed fields: needs recalculation
  computed_at    timestamptz,                            -- computed fields: last evaluation
  updated_by     uuid /* id -> identity.users */,
  updated_at     timestamptz NOT NULL DEFAULT now(),
  version        integer NOT NULL DEFAULT 1,
  PRIMARY KEY (task_id, field_id),
  CHECK (num_nonnulls(value_text, value_num, value_ts, value_bool, option_id, value_json) <= 1),
  CHECK (value_has_time IS NULL OR value_ts IS NOT NULL)
);

-- Filter/sort by a field across a list's tasks (join target); one index per value column that we filter on.
CREATE INDEX cfv_field_num_idx  ON custom_field_values (workspace_id, field_id, value_num)  WHERE value_num IS NOT NULL;

CREATE INDEX cfv_field_ts_idx   ON custom_field_values (workspace_id, field_id, value_ts)   WHERE value_ts IS NOT NULL;

CREATE INDEX cfv_field_text_idx ON custom_field_values (workspace_id, field_id, value_text) WHERE value_text IS NOT NULL;

CREATE INDEX cfv_field_opt_idx  ON custom_field_values (workspace_id, field_id, option_id)  WHERE option_id IS NOT NULL;

CREATE INDEX cfv_field_bool_idx ON custom_field_values (workspace_id, field_id, value_bool) WHERE value_bool IS NOT NULL;

-- Recalculation worker queue.
CREATE INDEX cfv_stale_idx ON custom_field_values (workspace_id, field_id, task_id) WHERE is_stale;

-- Set-valued content: labels, people, relationship targets, files. One row per member. PROVEN: set edits are add/remove lists.
CREATE TABLE custom_field_value_items (
  id             uuid PRIMARY KEY,
  workspace_id   uuid NOT NULL /* id -> access.workspaces */,
  task_id        uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  field_id       uuid NOT NULL REFERENCES custom_fields(id),
  option_id      uuid REFERENCES custom_field_options(id),   -- labels
  user_id        uuid /* id -> identity.users */,                  -- people
  group_id       uuid /* id -> access.user_groups */,            -- people (include_groups)
  ref_task_id    uuid REFERENCES tasks(id) ON DELETE CASCADE,-- relationship
  attachment_id  uuid,                                       -- files; FK to attachments(id) in the commented block at the end
  position       text COLLATE "C",
  created_at     timestamptz NOT NULL DEFAULT now(),
  CHECK (num_nonnulls(option_id, user_id, group_id, ref_task_id, attachment_id) = 1)
);

CREATE UNIQUE INDEX cfvi_option_uk ON custom_field_value_items (task_id, field_id, option_id)   WHERE option_id IS NOT NULL;

CREATE UNIQUE INDEX cfvi_user_uk   ON custom_field_value_items (task_id, field_id, user_id)     WHERE user_id IS NOT NULL;

CREATE UNIQUE INDEX cfvi_group_uk  ON custom_field_value_items (task_id, field_id, group_id)    WHERE group_id IS NOT NULL;

CREATE UNIQUE INDEX cfvi_ref_uk    ON custom_field_value_items (task_id, field_id, ref_task_id) WHERE ref_task_id IS NOT NULL;

CREATE UNIQUE INDEX cfvi_att_uk    ON custom_field_value_items (task_id, field_id, attachment_id) WHERE attachment_id IS NOT NULL;

-- Filter "label = X" / "person = me" across tasks.
CREATE INDEX cfvi_field_option_idx ON custom_field_value_items (workspace_id, field_id, option_id, task_id) WHERE option_id IS NOT NULL;

CREATE INDEX cfvi_field_user_idx   ON custom_field_value_items (workspace_id, field_id, user_id, task_id)   WHERE user_id IS NOT NULL;

-- Reverse relationship / rollup: "who points at task T" and backlink maintenance.
CREATE INDEX cfvi_ref_task_idx     ON custom_field_value_items (workspace_id, ref_task_id, field_id) WHERE ref_task_id IS NOT NULL;

CREATE INDEX cfvi_task_field_idx   ON custom_field_value_items (workspace_id, task_id, field_id);

-- Computed fields. Parsed expression stored (PROVEN: formula editor + 73-function library; server-vs-client evaluation
-- is an OPEN question). Everything else ASSUMED.
CREATE TABLE custom_field_computation (
  field_id             uuid PRIMARY KEY REFERENCES custom_fields(id) ON DELETE CASCADE,
  workspace_id         uuid NOT NULL /* id -> access.workspaces */,
  kind                 text NOT NULL CHECK (kind IN ('formula','rollup')),
  -- formula
  expression_text      text,                             -- as typed by the user
  expression_tree      jsonb,                            -- parsed AST, evaluated by the engine, never queried
  -- rollup
  rollup_relation_field_id uuid REFERENCES custom_fields(id),
  rollup_target_field_id   uuid REFERENCES custom_fields(id),
  rollup_target_builtin    text CHECK (rollup_target_builtin IN ('time_estimate','points','due_at','start_at','status_category','task_count')),
  rollup_function      text CHECK (rollup_function IN ('sum','average','min','max','count','earliest','latest','percent_done')),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  version              integer NOT NULL DEFAULT 1,
  CHECK ( (kind = 'formula' AND expression_text IS NOT NULL AND rollup_function IS NULL)
       OR (kind = 'rollup'  AND rollup_relation_field_id IS NOT NULL AND rollup_function IS NOT NULL
           AND num_nonnulls(rollup_target_field_id, rollup_target_builtin) = 1) )
);

CREATE INDEX cfc_ws_idx ON custom_field_computation (workspace_id, kind);

-- Dependency edges: dependent_field_id reads depends_on (another field or a built-in column).
-- via_relation_field_id is set when the input is read through a relationship (rollup). Cycles rejected at save (app, DFS). ASSUMED
CREATE TABLE custom_field_dependencies (
  id                    uuid PRIMARY KEY,
  workspace_id          uuid NOT NULL /* id -> access.workspaces */,
  dependent_field_id    uuid NOT NULL REFERENCES custom_fields(id) ON DELETE CASCADE,
  depends_on_field_id   uuid REFERENCES custom_fields(id),
  depends_on_builtin    text CHECK (depends_on_builtin IN ('time_estimate','points','due_at','start_at','status_category','priority','assignees','tags')),
  via_relation_field_id uuid REFERENCES custom_fields(id),
  CHECK (num_nonnulls(depends_on_field_id, depends_on_builtin) = 1),
  CHECK (depends_on_field_id IS DISTINCT FROM dependent_field_id)
);

CREATE UNIQUE INDEX cfd_field_uk   ON custom_field_dependencies (dependent_field_id, depends_on_field_id, COALESCE(via_relation_field_id, '00000000-0000-0000-0000-000000000000'::uuid)) WHERE depends_on_field_id IS NOT NULL;

CREATE UNIQUE INDEX cfd_builtin_uk ON custom_field_dependencies (dependent_field_id, depends_on_builtin, COALESCE(via_relation_field_id, '00000000-0000-0000-0000-000000000000'::uuid)) WHERE depends_on_builtin IS NOT NULL;

-- On a value change: "which computed fields depend on field F" (propagation).
CREATE INDEX cfd_reverse_idx ON custom_field_dependencies (workspace_id, depends_on_field_id) WHERE depends_on_field_id IS NOT NULL;

CREATE INDEX cfd_builtin_rev_idx ON custom_field_dependencies (workspace_id, depends_on_builtin) WHERE depends_on_builtin IS NOT NULL;

-- filter entries by tag

-- estimates: PROVEN task.time_estimate (ms) + time_estimate_string; per-person allocation PROVEN as a request, shape ASSUMED.
-- rolled_up_* are derived (sum over subtasks) and not stored.
CREATE TABLE task_time_estimates (
  task_id uuid PRIMARY KEY REFERENCES tasks(id) ON DELETE CASCADE,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  estimate_ms bigint NOT NULL CHECK (estimate_ms >= 0),
  estimate_text text,                                -- PROVEN e.g. '12 hours'; what the user typed
  updated_by uuid /* id -> identity.users */,
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE INDEX task_time_estimates_ws ON task_time_estimates (workspace_id);

CREATE TABLE task_assignee_estimates (               -- ASSUMED (time_allocations/bulk)
  task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  user_id uuid NOT NULL /* id -> identity.users */,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  estimate_ms bigint NOT NULL CHECK (estimate_ms >= 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (task_id, user_id)
);

CREATE INDEX task_assignee_estimates_user ON task_assignee_estimates (workspace_id, user_id);

-- Sprints, sprint points and templates. Run AFTER core-schema.sql (needs workspaces, users, spaces, folders, lists, containers, tasks).
-- PROVEN = from captured requests / UI (plan/captures-sprints-templates.md). ASSUMED = our design.

-- ---------------------------------------------------------------- TEMPLATES (first: sprint settings point at it)
CREATE TABLE templates (
  id                  uuid PRIMARY KEY,
  workspace_id        uuid NOT NULL /* id -> access.workspaces */,
  kind                text NOT NULL CHECK (kind IN ('space','folder','list','task','doc','view','whiteboard')),  -- PROVEN type filter list (art kit, super agent, skill not modelled)
  name                text NOT NULL,
  description         text,
  visibility          smallint NOT NULL DEFAULT 4,          -- PROVEN: 4 = members and admins; other codes ASSUMED
  public_sharing      boolean NOT NULL DEFAULT false,       -- PROVEN
  source_container_id uuid /* id -> hierarchy.containers */,  -- ASSUMED: where it was saved from
  include_flags       jsonb NOT NULL DEFAULT '{}',          -- PROVEN ~25 booleans (old_assignees, custom_fields, include_views, automation, ...). Config only, never filtered on
  created_by          uuid /* id -> identity.users */,
  deleted_at          timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  version             integer NOT NULL DEFAULT 1
);

CREATE INDEX templates_ws_kind_idx ON templates (workspace_id, kind, name) WHERE deleted_at IS NULL;

-- Template Center "workspace templates" tab, filtered by type

-- Frozen content, kept apart so listing templates never loads big payloads. ASSUMED design: a JSON tree with LOCAL ids
-- (containers, statuses, fields, views, tasks, automations), remapped to new uuids at apply time.
CREATE TABLE template_snapshots (
  template_id    uuid PRIMARY KEY REFERENCES templates(id) ON DELETE CASCADE,
  format_version integer NOT NULL,
  payload        jsonb NOT NULL,
  summary        jsonb NOT NULL DEFAULT '{}'      -- PROVEN UI "Template includes": status groups, custom fields, sprints, view types (counts)
);

CREATE TABLE template_tags (
  template_id uuid NOT NULL REFERENCES templates(id) ON DELETE CASCADE,
  tag         text NOT NULL,
  PRIMARY KEY (template_id, tag)
);

CREATE INDEX template_tags_tag_idx ON template_tags (tag);

-- One row per "Use template" click. PROVEN request has return_immediately:true, so the copy is asynchronous; the job row is ASSUMED.
CREATE TABLE template_apply_jobs (
  id                  uuid PRIMARY KEY,
  workspace_id        uuid NOT NULL /* id -> access.workspaces */,
  template_id         uuid NOT NULL REFERENCES templates(id),
  target_container_id uuid NOT NULL /* id -> hierarchy.containers */,   -- PROVEN: space (project_id) or parent folder (parent_category_id)
  name_override       text,                                       -- PROVEN: blank name = use template name
  options             jsonb NOT NULL DEFAULT '{}',                -- PROVEN: import everything | custom items, remap dates, archived mode (0,1,unarchive)
  status              text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','done','failed')),
  error               text,
  requested_by        uuid /* id -> identity.users */,
  created_at          timestamptz NOT NULL DEFAULT now(),
  finished_at         timestamptz
);

CREATE INDEX template_apply_jobs_ws_idx ON template_apply_jobs (workspace_id, created_at DESC);

CREATE INDEX template_apply_jobs_open_idx ON template_apply_jobs (status) WHERE status IN ('queued','running');

-- worker pickup

-- Audit and cross-reference repair (Template Center has an Audit Log, PROVEN). ASSUMED table.
CREATE TABLE template_apply_id_map (
  job_id   uuid NOT NULL REFERENCES template_apply_jobs(id) ON DELETE CASCADE,
  kind     text NOT NULL,
  local_id uuid NOT NULL,
  new_id   uuid NOT NULL,
  PRIMARY KEY (job_id, kind, local_id)
);

-- tasks.points (core-schema) holds the single value; when per_assignee is on, the split lives here.
CREATE TABLE task_assignee_points (
  task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  user_id uuid NOT NULL /* id -> identity.users */,
  points  numeric(10,2) NOT NULL,
  PRIMARY KEY (task_id, user_id)
);

-- =============================================================================
-- 3. TASK extras: checklists, status history, merges, recurrence  (FR-103, FR-308, FR-123, FR-112)
-- =============================================================================
CREATE TABLE task_checklists (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  name text NOT NULL,
  position text NOT NULL COLLATE "C",
  created_by uuid /* id -> identity.users */,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE INDEX task_checklists_task_idx ON task_checklists (workspace_id, task_id, position) WHERE deleted_at IS NULL;

CREATE TABLE task_checklist_items (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  checklist_id uuid NOT NULL REFERENCES task_checklists(id) ON DELETE CASCADE,
  parent_item_id uuid REFERENCES task_checklist_items(id) ON DELETE CASCADE,   -- nested items, ASSUMED
  text text NOT NULL,
  assignee_id uuid /* id -> identity.users */,
  resolved_at timestamptz,
  resolved_by uuid /* id -> identity.users */,
  position text NOT NULL COLLATE "C",
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  CHECK (parent_item_id IS NULL OR parent_item_id <> id)
);

CREATE INDEX task_checklist_items_idx ON task_checklist_items (workspace_id, checklist_id, position);

-- Status history: one row per stay in a status. Written by the same transaction as the status change
-- (and rebuildable from change_log). Feeds time-in-status, cycle/lead time, cumulative flow. FR-308, DR-016, L-04.
CREATE TABLE task_status_history (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  id uuid NOT NULL,
  task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  status_id uuid NOT NULL /* id -> hierarchy.task_statuses */,
  category text NOT NULL,                                -- copy of category at the time, categories can be renamed
  entered_at timestamptz NOT NULL,
  left_at timestamptz,                                   -- NULL = current stay
  entered_by uuid /* id -> identity.users */,
  source text NOT NULL DEFAULT 'ui' CHECK (source IN ('ui','mobile','api','automation','import','system','form')),
  PRIMARY KEY (workspace_id, id),
  CHECK (left_at IS NULL OR left_at >= entered_at)
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('task_status_history', 8);

CREATE UNIQUE INDEX task_status_history_open ON task_status_history (workspace_id, task_id) WHERE left_at IS NULL;

CREATE INDEX task_status_history_task ON task_status_history (workspace_id, task_id, entered_at);

CREATE INDEX task_status_history_status_day ON task_status_history (workspace_id, status_id, entered_at);

