ALTER TABLE templates ADD COLUMN is_curated boolean NOT NULL DEFAULT false;

-- FR-708
DO $$
DECLARE c text;
BEGIN
  SELECT conname INTO c FROM pg_constraint WHERE conrelid = 'templates'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%whiteboard%';
  IF c IS NOT NULL THEN EXECUTE format('ALTER TABLE templates DROP CONSTRAINT %I', c); END IF;
END $$;

ALTER TABLE templates ADD CONSTRAINT templates_kind_chk
  CHECK (kind IN ('space','folder','list','task','doc','view','whiteboard','dashboard','form'));

-- =============================================================================
-- 6. FORMULA ENGINE GAP found 6 Nov 2026: cost in ClickUp is built as a Formula field (rate x time tracked). core-schema could not express
-- 'time tracked' or a per-user people field as a formula input or rollup target. Fixed here. ASSUMED design.
-- Propagation: a time_entries change writes change_log, the field-compute consumer recomputes formulas that depend on time_tracked for that task.
-- =============================================================================
DO $$
DECLARE c text;
BEGIN
  FOR c IN SELECT conname FROM pg_constraint
            WHERE conrelid = 'custom_field_dependencies'::regclass AND contype = 'c'
              AND (pg_get_constraintdef(oid) ILIKE '%depends_on_builtin%' OR pg_get_constraintdef(oid) ILIKE '%num_nonnulls%')
  LOOP EXECUTE format('ALTER TABLE custom_field_dependencies DROP CONSTRAINT %I', c); END LOOP;
  FOR c IN SELECT conname FROM pg_constraint
            WHERE conrelid = 'custom_field_computation'::regclass AND contype = 'c'
              AND pg_get_constraintdef(oid) ILIKE '%rollup_target_builtin%'
  LOOP EXECUTE format('ALTER TABLE custom_field_computation DROP CONSTRAINT %I', c); END LOOP;
END $$;

ALTER TABLE custom_field_dependencies ADD COLUMN depends_on_people_field_id uuid /* id -> access.people_field_defs */;

ALTER TABLE custom_field_dependencies ADD CONSTRAINT cfd_builtin_chk CHECK (depends_on_builtin IN (
  'time_estimate','points','due_at','start_at','status_category','priority','assignees','tags',
  'time_tracked','time_tracked_billable','time_tracked_non_billable','time_tracked_by_assignee',
  -- rolled up = task plus all subtasks (PROVEN need: client Actual Cost and Remaining Hours, 95-client-export-findings.md)
  'time_tracked_rolled_up','time_estimate_rolled_up','points_rolled_up','date_created','date_closed','date_done'));

ALTER TABLE custom_field_dependencies ADD CONSTRAINT cfd_one_source_chk
  CHECK (num_nonnulls(depends_on_field_id, depends_on_builtin, depends_on_people_field_id) = 1);

ALTER TABLE custom_field_computation ADD CONSTRAINT cfc_builtin_chk CHECK (rollup_target_builtin IN (
  'time_estimate','points','due_at','start_at','status_category','task_count',
  'time_tracked','time_tracked_billable','time_tracked_non_billable'));

CREATE UNIQUE INDEX cfd_people_uk ON custom_field_dependencies (dependent_field_id, depends_on_people_field_id)
  WHERE depends_on_people_field_id IS NOT NULL;

-- ===== NEW for the split: local copies kept from events (plan/tech/03-events.md section 6)
-- Rule: a copy is read-only for this service, has source_version, and an older event never overwrites a newer row.

CREATE TABLE list_copies (
  list_id         uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL,
  space_id        uuid NOT NULL,
  folder_id       uuid,
  status_set_id   uuid NOT NULL,
  archived        boolean NOT NULL DEFAULT false,
  deleted         boolean NOT NULL DEFAULT false,
  source_version  integer NOT NULL
);
CREATE INDEX list_copies_ws_idx ON list_copies (workspace_id);

CREATE TABLE status_copies (
  status_id       uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL,
  status_set_id   uuid NOT NULL,
  name            text NOT NULL,
  category        text NOT NULL CHECK (category IN ('open','custom','done','closed')),
  position        text NOT NULL COLLATE "C",
  deleted         boolean NOT NULL DEFAULT false,
  source_version  integer NOT NULL
);
CREATE INDEX status_copies_set_idx ON status_copies (workspace_id, status_set_id);

-- fields that must be filled before a task may enter a status (hierarchy.status_required_fields)
CREATE TABLE status_required_field_copies (
  workspace_id    uuid NOT NULL,
  status_id       uuid NOT NULL,
  field_id        uuid NOT NULL,
  PRIMARY KEY (workspace_id, status_id, field_id)
);

CREATE TABLE task_type_copies (
  task_type_id    uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL,
  name            text NOT NULL,
  deleted         boolean NOT NULL DEFAULT false,
  source_version  integer NOT NULL
);

CREATE TABLE member_copies (
  workspace_id    uuid NOT NULL,
  user_id         uuid NOT NULL,
  role_kind       text NOT NULL,
  status          text NOT NULL,
  source_version  integer NOT NULL,
  PRIMARY KEY (workspace_id, user_id)
);

-- number and money people-field values that formulas may read (rate per person)
CREATE TABLE people_value_copies (
  workspace_id    uuid NOT NULL,
  user_id         uuid NOT NULL,
  field_id        uuid NOT NULL,
  number_value    numeric(20,6),
  money_cents     bigint,
  money_currency  char(3),
  source_version  integer NOT NULL,
  PRIMARY KEY (workspace_id, user_id, field_id)
);

-- Time per task, from time entry.* events. Kept per entry so a repeat or a late event can never double count.
CREATE TABLE time_entry_copies (
  entry_id        uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL,
  task_id         uuid NOT NULL,
  user_id         uuid NOT NULL,
  duration_ms     bigint NOT NULL,
  billable        boolean NOT NULL,
  deleted         boolean NOT NULL DEFAULT false,
  source_version  integer NOT NULL
);
CREATE INDEX time_entry_copies_task_idx ON time_entry_copies (workspace_id, task_id);

-- Totals the formula engine and views read ("time logged"; "rolled up" = task plus all subtasks).
-- Updated in the same transaction as time_entry_copies by adding the difference.
CREATE TABLE task_time_totals (
  workspace_id    uuid NOT NULL,
  task_id         uuid NOT NULL,
  tracked_ms      bigint NOT NULL DEFAULT 0,
  billable_ms     bigint NOT NULL DEFAULT 0,
  rolled_up_ms    bigint NOT NULL DEFAULT 0,         -- self + descendants, maintained up the parent chain
  rolled_up_billable_ms bigint NOT NULL DEFAULT 0,
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, task_id)
);

-- Human task numbers (#123) without a hot row: each pod reserves a block of 100 numbers at a time.
-- Numbers stay unique per workspace; gaps are allowed.
CREATE TABLE task_number_blocks (
  workspace_id    uuid PRIMARY KEY,
  next_free       bigint NOT NULL DEFAULT 1
);

-- Decision D18 (plan/tech/12-decisions.md): the rich task description uses the same rich-text JSON as collab.comments.body.
-- description stays as the plain/markdown projection for search, events and email.
ALTER TABLE tasks ADD COLUMN description_doc jsonb;


-- ===== _epilogue.sql =====
-- Loaded LAST into every service database (hand-written, not generated).
-- 1) version trigger on every table that has version + updated_at
-- 2) row-level security on every table with a NOT NULL workspace_id (plan/tech/09-security.md)
-- Contract: through PgBouncer in transaction mode, every transaction starts with
--   SELECT set_config('app.workspace_id', '<uuid>', true);   -- true = this transaction only
-- A session-level SET would leak to the next client of the pooled connection, so it is forbidden.

DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.columns v ON v.table_schema = c.table_schema AND v.table_name = c.table_name AND v.column_name = 'updated_at'
    JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name AND t.table_type = 'BASE TABLE'
    WHERE c.table_schema = current_schema() AND c.column_name = 'version'
      AND NOT EXISTS (SELECT 1 FROM pg_trigger g WHERE g.tgrelid = (quote_ident(c.table_name))::regclass AND g.tgname = c.table_name || '_bump_version')
  LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION bump_version()',
                   r.table_name || '_bump_version', r.table_name);
  END LOOP;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user') THEN CREATE ROLE app_user NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_worker') THEN CREATE ROLE app_worker NOLOGIN BYPASSRLS; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_migrator') THEN CREATE ROLE app_migrator NOLOGIN; END IF;
END $$;

DO $$
DECLARE t record;
BEGIN
  FOR t IN
    SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = current_schema()
      JOIN pg_attribute a ON a.attrelid = c.oid AND a.attname = 'workspace_id' AND NOT a.attisdropped
     WHERE c.relkind IN ('r','p') AND NOT c.relispartition AND a.attnotnull
       AND c.relname NOT IN ('outbox','inbox')        -- written by the app, read only by Debezium / the consumer itself
       AND coalesce(obj_description(c.oid, 'pg_class'), '') NOT LIKE 'rls:exempt%'   -- global services mark routing tables
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t.relname);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t.relname);
    EXECUTE format('DROP POLICY IF EXISTS workspace_isolation ON %I', t.relname);
    EXECUTE format('CREATE POLICY workspace_isolation ON %I USING (workspace_id = current_workspace()) WITH CHECK (workspace_id = current_workspace())', t.relname);
  END LOOP;
END $$;

GRANT USAGE ON SCHEMA public TO app_user, app_worker;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_user, app_worker;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app_user, app_worker;
-- Tables with a nullable workspace_id (built-in rows) are not covered above; services add their own policy.
-- hierarchy: status_templates (built-ins have NULL workspace_id)
DO $$ BEGIN
  IF to_regclass('status_templates') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE status_templates ENABLE ROW LEVEL SECURITY';
    EXECUTE 'DROP POLICY IF EXISTS status_templates_read ON status_templates';
    EXECUTE 'DROP POLICY IF EXISTS status_templates_write ON status_templates';
    EXECUTE 'CREATE POLICY status_templates_read ON status_templates FOR SELECT USING (workspace_id IS NULL OR workspace_id = current_workspace())';
    EXECUTE 'CREATE POLICY status_templates_write ON status_templates FOR ALL USING (workspace_id = current_workspace()) WITH CHECK (workspace_id = current_workspace())';
  END IF;
  -- audit: append-only for the app roles
  IF to_regclass('audit_log') IS NOT NULL THEN
    EXECUTE 'REVOKE UPDATE, DELETE, TRUNCATE ON audit_log, security_events, data_access_log FROM app_user, app_worker';
  END IF;
END $$;

